#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  # explorer.exe mishandles URLs with '?' or '&' (it opens File Explorer and
  # exits 1), so on WSL hand the URL to Windows' default browser via PowerShell.
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v powershell.exe >/dev/null 2>&1; then
      powershell.exe -NoProfile -Command "Start-Process '${url//\'/\'\'}'"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Abogi step 1 owner setup: Google Calendar OAuth, Foundry tracing, .env.
# Run from anywhere:  scripts/owner-setup.sh
#
# Docs this wizard follows (checked 2026-11-10):
#   https://developers.google.com/workspace/calendar/api/guides/configure-mcp-server
#   https://support.google.com/cloud/answer/15549945   (Testing = 7-day refresh tokens)
#   https://learn.microsoft.com/en-us/azure/foundry/observability/how-to/trace-agent-setup
#   https://learn.microsoft.com/en-us/azure/foundry/agents/quickstarts/quickstart-hosted-agent

TOTAL_STAGES=9

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$REPO_ROOT/.env"
SECRETS_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/abogi"
CLIENT_SECRET_FILE="$SECRETS_DIR/google-oauth-client.json"
CALENDAR_MCP_DEFAULT_URL="https://calendarmcp.googleapis.com/mcp/v1"

ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; exit 1; }

# Prompts loop until answered, so refuse to run without a human at the keyboard.
[[ -t 0 ]] || fail "run this wizard in an interactive terminal (stdin is not a TTY)."

banner "Abogi step 1: owner setup"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Preflight: make sure .env can never be committed"
say "Values land in $ENV_FILE. Checking git ignores it before anything is written."
git -C "$REPO_ROOT" rev-parse --is-inside-work-tree >/dev/null 2>&1 \
  || fail "$REPO_ROOT is not a git checkout; stopping."
git -C "$REPO_ROOT" check-ignore -q .env \
  || fail ".env is NOT ignored by git. Add '.env' to .gitignore, then re-run."
if git -C "$REPO_ROOT" ls-files --error-unmatch .env >/dev/null 2>&1; then
  fail ".env is already tracked by git. Run 'git rm --cached .env', then re-run."
fi
ok ".env is git-ignored ($(git -C "$REPO_ROOT" check-ignore -v .env | cut -f1))"
note "Secrets you paste are typed hidden and never echoed back."
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: create or choose a project"
say "Abogi needs a Google Cloud project to own the Calendar OAuth client."
open_url "https://console.cloud.google.com/projectselector2/home/dashboard"
step "Pick an existing project, or click 'New project', name it (e.g. abogi), click 'Create'."
step "Copy the Project ID (not the display name) from the project picker or dashboard."
GCP_PROJECT_ID="${GCP_PROJECT_ID:-}"
while [[ -z "$GCP_PROJECT_ID" ]]; do
  printf '  %sProject ID:%s ' "$BOLD" "$RESET"; read -r GCP_PROJECT_ID || fail "input closed"
done
note "Project ID is kept for this run only, to build console links."
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: enable the Calendar API and the Calendar MCP API"
say "Google's remote Calendar MCP server needs BOTH services enabled:"
say "  calendar-json.googleapis.com  (Google Calendar API)"
say "  calendarmcp.googleapis.com    (Google Calendar MCP API)"
HAVE_GCLOUD=0; command -v gcloud >/dev/null 2>&1 && HAVE_GCLOUD=1
if (( HAVE_GCLOUD )) && confirm "gcloud is installed. Enable both with gcloud now?"; then
  if gcloud services enable calendar-json.googleapis.com calendarmcp.googleapis.com --project="$GCP_PROJECT_ID"; then
    ok "both services enabled"
  else
    warn "gcloud failed; use the console pages below instead."
  fi
fi
open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com?project=$GCP_PROJECT_ID"
step "Click 'Enable' (if it shows 'Manage', it's already on)."
pause "Calendar API enabled? Press Enter"
open_url "https://console.cloud.google.com/apis/library/calendarmcp.googleapis.com?project=$GCP_PROJECT_ID"
step "Click 'Enable' for the Google Calendar MCP API."
pause "Calendar MCP API enabled? Press Enter"
if (( HAVE_GCLOUD )); then
  enabled=$(gcloud services list --enabled --project="$GCP_PROJECT_ID" --format='value(config.name)' 2>/dev/null || true)
  for svc in calendar-json.googleapis.com calendarmcp.googleapis.com; do
    if grep -qx "$svc" <<<"$enabled"; then ok "$svc enabled"
    else warn "$svc not listed as enabled yet"; SKIPPED+=("confirm $svc is enabled in $GCP_PROJECT_ID"); fi
  done
else
  note "gcloud not found, so this can't be verified automatically."
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: OAuth consent screen (Google Auth Platform)"
open_url "https://console.cloud.google.com/auth/branding?project=$GCP_PROJECT_ID"
step "Branding: if prompted click 'Get started'. App name: Abogi. User support email: yours. Next."
step "Audience: choose 'External' (a personal Gmail account has no 'Internal'). Next."
step "Contact information: your email. Next. Agree to the policy, 'Continue', then 'Create'."
pause "Consent screen created? Press Enter"
open_url "https://console.cloud.google.com/auth/audience?project=$GCP_PROJECT_ID"
step "Audience > Test users > 'Add users': add YOUR OWN Google account, then 'Save'."
warn "While the publishing status is 'Testing', refresh tokens expire after 7 days."
note "Expect invalid_grant weekly: sign in again, or later 'Publish app' to end the expiry."
pause "Test user added? Press Enter"
open_url "https://console.cloud.google.com/auth/scopes?project=$GCP_PROJECT_ID"
step "Data access > 'Add or remove scopes' > 'Manually add scopes'. Paste these,"
step "click 'Add to table', 'Update', then 'Save' on the Data access page:"
note "  https://www.googleapis.com/auth/calendar.calendarlist.readonly"
note "  https://www.googleapis.com/auth/calendar.events.freebusy"
note "  https://www.googleapis.com/auth/calendar.events.readonly"
note "  https://www.googleapis.com/auth/calendar.events   (only if Abogi should create/edit events)"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: create the OAuth client"
say "How will Abogi reach the Calendar MCP server?"
say "  1) directly from Abogi's own code, with a local OAuth sign-in  [default]"
say "  2) through a Foundry toolbox that holds the OAuth connection"
printf '  %sChoose 1 or 2:%s ' "$BOLD" "$RESET"; CAL_ROUTE=""; read -r CAL_ROUTE || true
[[ "$CAL_ROUTE" == "2" ]] || CAL_ROUTE=1
open_url "https://console.cloud.google.com/auth/clients/create?project=$GCP_PROJECT_ID"
if [[ "$CAL_ROUTE" == "1" ]]; then
  step "Application type: 'Desktop app'. Name: abogi-local. Click 'Create'."
  note "Desktop clients redirect to localhost, so no redirect URI is needed."
else
  step "Application type: 'Web application'. Name: abogi-foundry."
  step "Tick 'Use this client for an AI-powered agent' if it's offered."
  step "Authorized redirect URIs > '+ Add URI': paste the redirect URI Foundry shows when"
  step "you create the OAuth connection for the toolbox. Click 'Create'."
fi
step "In the 'OAuth client created' dialog, click 'Download JSON' NOW."
warn "Google may show the client secret only once. If you closed the dialog without"
warn "downloading, open the client and add a new secret instead."
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Store the client secret JSON outside the repo"
say "The JSON goes to $CLIENT_SECRET_FILE (mode 600), never into the repo."
if [[ -f "$CLIENT_SECRET_FILE" ]] && confirm "A client file is already there. Keep it?"; then
  ok "keeping existing $CLIENT_SECRET_FILE"
else
  win_user=$(cmd.exe /c 'echo %USERNAME%' 2>/dev/null | tr -d '\r' || true)
  [[ -n "$win_user" ]] && note "WSL tip: Windows Downloads is /mnt/c/Users/$win_user/Downloads/"
  src=""
  while :; do
    printf '  %sPath to the downloaded client_secret_*.json:%s ' "$BOLD" "$RESET"; read -r src || fail "input closed"
    src="${src%\"}"; src="${src#\"}"; src="${src/#\~/$HOME}"
    [[ -f "$src" ]] || { warn "no file at: $src"; continue; }
    if ! grep -q '"client_id"' "$src" || ! grep -q '"client_secret"' "$src"; then
      warn "that isn't an OAuth client JSON (no client_id / client_secret)"; continue
    fi
    break
  done
  mkdir -p "$SECRETS_DIR" && chmod 700 "$SECRETS_DIR"
  if confirm "Move it (rather than copy), so no stray copy stays in Downloads?"; then
    mv "$src" "$CLIENT_SECRET_FILE"
  else
    cp "$src" "$CLIENT_SECRET_FILE"; SKIPPED+=("delete the leftover copy at $src")
  fi
  chmod 600 "$CLIENT_SECRET_FILE"
fi
real_secret=$(realpath "$CLIENT_SECRET_FILE")
[[ "$real_secret" != "$REPO_ROOT"/* ]] || fail "client JSON resolves inside the repo ($real_secret); move it out and re-run."
[[ "$(stat -c '%a' "$CLIENT_SECRET_FILE")" == "600" ]] || chmod 600 "$CLIENT_SECRET_FILE"
ok "stored $CLIENT_SECRET_FILE (mode 600, contents not shown)"
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Foundry: connect Application Insights to project 'abogi'"
say "Connecting Application Insights turns on server-side tracing for the project's agents."
open_url "https://ai.azure.com/"
step "Make sure the 'New Foundry' toggle at the top is ON, then open project 'abogi'."
step "Left nav: Build > Agents. At the top, select 'Traces'."
step "On the right, select 'Connect'. Pick an existing Application Insights resource and"
step "'Connect', or 'Create new' and finish its wizard. Wait for the confirmation message."
note "No 'Connect' button? Manage (upper right) > Project details > Connected resources >"
note "Add connection > Application Insights."
note "Reading traces needs the 'Log Analytics Reader' role on that Application Insights resource."
if confirm "Did you see the connection-succeeded confirmation?"; then
  ok "tracing connected"
else
  SKIPPED+=("connect Application Insights: Foundry > abogi > Build > Agents > Traces > Connect")
fi
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Foundry: project endpoint and model deployment"
open_url "https://ai.azure.com/"
step "In project 'abogi', open the project Home page and copy the 'Project endpoint'."
note "Format: https://<resource>.services.ai.azure.com/api/projects/abogi"
ask ABOGI_PROJECT_ENDPOINT "Project endpoint:"
until [[ "$ABOGI_PROJECT_ENDPOINT" =~ ^https://[^/]+/api/projects/[^/]+/?$ ]]; do
  warn "expected https://<resource>.services.ai.azure.com/api/projects/<project>"
  ask ABOGI_PROJECT_ENDPOINT "Project endpoint:"
done
write_env ABOGI_PROJECT_ENDPOINT "${ABOGI_PROJECT_ENDPOINT%/}"
step "Build > Models: copy the DEPLOYMENT name (not the model name) Abogi should call."
ask AZURE_AI_MODEL_DEPLOYMENT_NAME "Model deployment name:"
until [[ -n "$AZURE_AI_MODEL_DEPLOYMENT_NAME" ]]; do
  ask AZURE_AI_MODEL_DEPLOYMENT_NAME "Model deployment name:"
done
write_env AZURE_AI_MODEL_DEPLOYMENT_NAME "$AZURE_AI_MODEL_DEPLOYMENT_NAME"
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Calendar connector values"
if [[ "$CAL_ROUTE" == "1" ]]; then
  say "Direct route: Abogi calls Google's Calendar MCP server itself."
  ask ABOGI_CALENDAR_MCP_URL "Calendar MCP URL (Enter for $CALENDAR_MCP_DEFAULT_URL):"
  [[ -n "$ABOGI_CALENDAR_MCP_URL" ]] || ABOGI_CALENDAR_MCP_URL="$CALENDAR_MCP_DEFAULT_URL"
  write_env ABOGI_CALENDAR_MCP_URL "$ABOGI_CALENDAR_MCP_URL"
  say "Paste an OAuth access token for it if you already have one (hidden), or press Enter"
  say "to leave it to Abogi's sign-in flow, which uses $CLIENT_SECRET_FILE."
  note "Access tokens last about an hour, so a pasted token is only good for a quick smoke test."
  ask_secret ABOGI_CALENDAR_MCP_TOKEN "Access token (optional):"
  if [[ -n "$ABOGI_CALENDAR_MCP_TOKEN" ]]; then
    write_env ABOGI_CALENDAR_MCP_TOKEN "$ABOGI_CALENDAR_MCP_TOKEN"
  else
    note "left ABOGI_CALENDAR_MCP_TOKEN unset"
  fi
else
  say "Toolbox route: Foundry holds the OAuth connection; Abogi only needs the toolbox name."
  open_url "https://ai.azure.com/"
  step "In project 'abogi', find the toolbox that wraps $CALENDAR_MCP_DEFAULT_URL and copy its name."
  ask ABOGI_CALENDAR_TOOLBOX "Toolbox name:"
  until [[ -n "$ABOGI_CALENDAR_TOOLBOX" ]]; do ask ABOGI_CALENDAR_TOOLBOX "Toolbox name:"; done
  write_env ABOGI_CALENDAR_TOOLBOX "$ABOGI_CALENDAR_TOOLBOX"
fi
chmod 600 "$ENV_FILE"
git -C "$REPO_ROOT" check-ignore -q .env && ok "$ENV_FILE is still git-ignored, mode 600"
pause

finish
note "Google OAuth client JSON: $CLIENT_SECRET_FILE"
note "Reminder: Testing-mode refresh tokens expire every 7 days."
